"""Publish only compact summary fields and displayed figures from pinned canonical evidence."""
from pathlib import Path
import argparse,json,html,os,tempfile,hashlib
os.environ.setdefault("MPLCONFIGDIR",str(Path(tempfile.gettempdir())/"labs-matplotlib"))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
R=Path(__file__).resolve().parents[1]
ENG=['nift','jinja','nunjucks','handlebars','liquid']
NAMES=['Nift','Jinja2','Nunjucks','Handlebars','LiquidJS']
COLORS=['#b8ff55','#ffb48c','#dba5ca','#ff87ad','#91d5bb']
plt.rcParams.update({'figure.facecolor':'#20221f','axes.facecolor':'#20221f','text.color':'#eeeae1','axes.labelcolor':'#eeeae1','xtick.color':'#b5b3a8','ytick.color':'#b5b3a8','axes.edgecolor':'#66695f','font.size':13,'svg.fonttype':'none','svg.hashsalt':'template-engines-20261011'})
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--evidence',type=Path);ap.add_argument('--commit');ap.add_argument('--experiment-commit');args=ap.parse_args()
 dest=R/'content/benchmarks/template-engines';assets=R/'public/benchmarks/template-engines/assets';assets.mkdir(parents=True,exist_ok=True)
 if args.evidence:
  raw=json.loads((args.evidence/'summary.json').read_text())
  assert raw['audit']['pass'] and raw['audit']['cells']==375 and raw['audit']['measured_observations']==17950
  assert raw['environment']['suite_sha']=='3c0dcdd1aad3cbb0a0c638c9041233b1e329dc6f'
  accepted=json.loads((args.evidence/'ACCEPTANCE.json').read_text());assert accepted['pass'] and accepted['candidate_sha']=='c14d06835bca515a5281e41da0e40219c2d60ef0'
  manifest=json.loads((args.evidence/'SHA256SUMS.json').read_text());assert hashlib.sha256((args.evidence/'summary.json').read_bytes()).hexdigest()==manifest['summary.json']
  assert args.commit and len(args.commit)==40
  args.experiment_commit=args.experiment_commit or raw['environment']['suite_sha']
  compact={'evidence_commit':args.commit,'experiment_commit':args.experiment_commit,'suite_sha':raw['environment']['suite_sha'],'series':'20261015-v4120-final-c14d068','source_summary_sha256':hashlib.sha256((args.evidence/'summary.json').read_bytes()).hexdigest(),'nift_source':raw['environment']['nift_source_sha'],'versions':{k:v for k,v in raw['environment']['tools'].items() if k in ['nift_version','jinja2','markupsafe','nunjucks','handlebars','liquidjs']},'counts':raw['audit'],'cells':raw['cells'],'worker_memory':[{k:x[k] for k in ['case','engine','mode','max_process_rss_mib']} for x in raw['worker_memory'] if x['case'] in ['literal','article','collection']]}
  (dest/'published.json').write_text(json.dumps(compact,separators=(',',':'))+'\n')
 else:
  compact=json.loads((dest/'published.json').read_text())
  args.commit=compact['evidence_commit'];args.experiment_commit=compact['experiment_commit']
 cells={(x['case'],x['engine'],x['mode']):x for x in compact['cells']}
 def mode_for(mode,eng):return 'source-reuse' if eng=='nift' and mode=='render' else mode
 def table(rows,mode,caption,metric='median_ms',factor=None):
  out='<div class="table-scroll" tabindex="0" role="region" aria-label="Results, horizontally scrollable"><table><caption>'+html.escape(caption)+'</caption><thead><tr><th scope="col">Workload</th>'+''.join('<th scope="col">'+n+'</th>' for n in NAMES)+'</tr></thead><tbody>'
  for case,label in rows:
   out+='<tr><th scope="row">'+html.escape(label)+'</th>'
   for eng in ENG:
    x=cells.get((case,eng,mode_for(mode,eng)))
    value=x[metric]*(factor(case) if factor else 1) if x else None
    out+='<td>'+ (f'{value:,.3f}' if value is not None else '<span title="Public prepared-template API unavailable">—</span>')+'</td>'
   out+='</tr>'
  return out+'</tbody></table></div>'
 def figure(slug,title,rows,mode,caption,metric='median_ms',factor=None,line=False,log=False):
  fig,ax=plt.subplots(figsize=(9.6,4.8));x=np.array([int(c.rsplit('-',1)[1]) for c,_ in rows]) if line else np.arange(len(rows));active=[e for e in ENG if any((c,e,mode_for(mode,e)) in cells for c,_ in rows)]
  for j,eng in enumerate(active):
   i=ENG.index(eng);values=[cells[(c,eng,mode_for(mode,eng))][metric]*(factor(c) if factor else 1) for c,_ in rows]
   if line:ax.plot(x,values,marker=['o','s','^','D','v'][i],color=COLORS[i],label=NAMES[i],linewidth=2,markersize=6)
   else:ax.bar(x+(j-(len(active)-1)/2)*.15,values,.14,color=COLORS[i],label=NAMES[i])
  if line:ax.set_xscale('log');ax.set_xlabel('Workload size · logarithmic scale')
  ax.set_xticks(x,[label for _,label in rows]);ax.tick_params(axis='x',labelsize=10);ax.set_ylabel('MiB / fresh child' if metric=='median_child_rss_mib' else 'Median milliseconds')
  if log:ax.set_yscale('log');ax.set_ylabel(ax.get_ylabel()+' · logarithmic scale')
  elif not line:ax.set_ylim(bottom=0)
  fig.text(.13,.96,title,ha='left',va='top',fontsize=14);ax.grid(axis='y',alpha=.18);ax.set_axisbelow(True)
  fig.legend(*ax.get_legend_handles_labels(),ncol=3,fontsize=10,frameon=False,loc='upper left',bbox_to_anchor=(.08,.89));ax.yaxis.label.set_size(10);fig.subplots_adjust(left=.13,right=.92,bottom=.17,top=.68)
  fig.savefig(assets/(slug+'.svg'),metadata={'Date':None})
  fig.savefig(assets/(slug+'.png'),dpi=150,pil_kwargs={'compress_level':9})
  plt.close(fig)
  return '<div class="measure"><figure><div class="plot-scroll" tabindex="0" role="region" aria-label="Chart, horizontally scrollable"><img src="assets/'+slug+'.svg" alt="'+html.escape(title)+'"></div><figcaption>'+html.escape(caption)+' <a href="assets/'+slug+'.svg">SVG</a> · <a href="assets/'+slug+'.png">PNG</a>. On narrow screens, scroll the chart and table horizontally.</figcaption></figure>'+table(rows,mode,caption,metric,factor)+'</div>'
 def section(id,kicker,title,body):return '<section class="report" id="'+id+'"><p class="eyebrow">'+kicker+'</p><h2>'+title+'</h2>'+body+'</section>'
 count=compact['counts'];suite=compact['suite_sha'];source=compact['nift_source'];evidence='https://github.com/nift-experiments/lab-evidence/tree/'+args.commit+'/benchmarks/template-engines/'+compact['series'];experiment='https://github.com/nift-experiments/template-engines/blob/'+args.experiment_commit
 out='''<main id="main"><div class="hero"><div><p class="eyebrow">Template engines / document assembly</p><h1>One template.<br>New data.<br><em>Exact output.</em></h1><p class="lede">Five engines assemble the same documents. What does preparation cost—and what happens when the next render arrives?</p></div><div class="compositor"><div class="machine-top"><span>ASSEMBLY / 001</span><span>BYTE CONTRACT</span></div><div class="layers"><div class="layer template"><span>01 / TEMPLATE</span>&lt;h1&gt;\\$[d.title]&lt;/h1&gt;<br>\\@input('footer')</div><div class="layer data"><span>02 / DATA</span>{ title: "Template lab",<br>&nbsp;author: { name: "Nick" } }</div><div class="layer output"><span>03 / OUTPUT</span>&lt;h1&gt;Template lab&lt;/h1&gt;<br>&lt;footer&gt;Nick&lt;/footer&gt;</div></div><div class="machine-foot">SOURCE + BINDINGS → RENDERER → CHECKED BYTES</div></div></div>'''
 out+='<div class="participants">'+''.join('<div><strong>'+name+' '+v+'</strong>'+kind+'</div>' for name,v,kind in [('Nift','4.12.0','Native embedded renderer'),('Jinja2','3.1.6','Python compiled templates'),('Nunjucks','3.2.4','JavaScript template runtime'),('Handlebars','4.7.10','Compiled presentation functions'),('LiquidJS','10.30.0','Constrained template model')])+'</div>'
 out+='<div class="counts"><span><b>'+f'{count["measured_observations"]:,}'+'</b>measured samples</span><span><b>375</b>supported cells</span><span><b>20</b>timed scenarios</span><span><b>'+str(count['warmup_observations'])+'</b>retained warmups</span></div>'
 out+='<nav class="jump" aria-label="Report sections">'+''.join('<a href="#'+i+'">'+n+'</a>' for i,n in [('contract','Contract'),('tiny','Fresh invocation'),('parse','Prepare'),('loops','Collections'),('again','Render again'),('composition','Compose'),('article','Real page'),('many','Many templates'),('memory','Memory'),('correctness','Correctness'),('practitioner','Practitioner view'),('method','Evidence')])+'</nav>'
 out+='<p class="note">Fresh article: Nift '+f'{cells[("article","nift","fresh")]["median_ms"]:.3f}'+' ms per invocation. Persistent 10,000-record render: Nift '+f'{cells[("loop-10000","nift","source-reuse")]["median_ms"]:.3f}'+' ms, Handlebars '+f'{cells[("loop-10000","handlebars","render")]["median_ms"]:.3f}'+' ms with preparation included. Low invocation cost does not establish sustained rendering throughput.</p>'
 out+=section('contract','01 / the contract','The document comes first.','''<p class="intro">Independent data and expected bytes define the task. Participant templates express the same literal text, values, branches, named records and include expansions. No tracked builds, generated sites or application servers are measured.</p><div class="contract"><article><p class="eyebrow">Fresh process</p><h3>Start → load → render</h3><p>Runtime startup, modules, source/data loading, complete rendering and stdout capture. Milliseconds per invocation.</p></article><article><p class="eyebrow">Persistent runtime</p><h3>Prepare → render</h3><p>Preloaded data and sources. Timed engine calls, batched where needed. Milliseconds per template operation.</p></article><article><p class="eyebrow">Prepared templates</p><h3>Render → render again</h3><p>Parsed/compiled artifacts reused where public APIs permit. Nift source reuse still parses; it has no exposed prepared-AST handle.</p></article></div><p class="note">The corpus is intentionally raw text. Automatic HTML escaping, contextual safety and untrusted-template sandboxing are not certified here. A separate special-character gate verifies that template-looking values remain data.</p>''')
 rows=[('literal','Literal'),('interpolation','Values'),('article','Article'),('loop-1000','1k records')]
 out+=section('tiny','02 / operational latency','A fresh process has a price.','<p>These totals include host-language startup, both frozen data variants, all scenario templates and complete intended output. A single render still preloads an unused second variant in every adapter. This is the reproducible harness boundary, not a hand-tuned minimal request or engine-only throughput.</p>'+figure('fresh','Fresh end-to-end invocation',rows,'fresh','Fresh invocation median ms; 30–50 measured samples per cell.'))
 rows=[('literal','Literal'),('interpolation','Values'),('article','Article')]
 out+=section('parse','03 / preparation','Before the first render.','<p>Jinja produces code, Nunjucks eager-compiles, Handlebars precompiles JavaScript source and LiquidJS parses tokens. These preparation artifacts differ. Nift exposes no standalone preparation API; its column is unavailable.</p>'+figure('prepare','Persistent preparation only',rows,'parse','Preparation median ms per template; 50 samples; logarithmic axis.',log=True))
 looprows=[('loop-'+str(n),f'{n:,} records') for n in [10,100,1000,10000]]
 out+=section('loops','04 / records and output','More rows. More work.','<p>Main source preparation plus rendering is timed on every operation. Nift uses its native render_text call. Preloaded contexts and output validation remain outside the timer.</p>'+figure('loops','Persistent source preparation + render',looprows,'render','Median ms per render; 50 samples; logarithmic axis.',line=True,log=True))
 out+=section('again','05 / prepared reuse','Preparation can be amortized.','<p>These four engines reuse prepared templates with preloaded data. Nift is absent because it does not expose the same capability. Keeping a Nift Engine alive avoids process startup, but does not turn source reuse into parsed-template reuse.</p>'+figure('reuse','Prepared-template rendering',looprows,'reuse','Median ms per prepared render; 50 samples; logarithmic axis; Nift API unavailable.',line=True,log=True)+figure('repeat','Prepared template, alternating new data',[('many-renders-100','100 renders'),('many-renders-1000','1,000 renders')],'reuse','Median total ms per repeated-render workload; 50 samples; logarithmic axis.',factor=lambda c:1000 if c.endswith('1000') else 100,line=True,log=True))
 rows=[('includes-'+str(n),f'Depth {n}') for n in [1,4,8]]
 out+=section('composition','06 / partials','Composition has two boundaries.','<p>Memory-backed sources use normal warmed partial caches where available, while main preparation repeats. File-backed calls load from files with engine source/partial caches invalidated or disabled. OS caches stay warm. Nift includes its supported root-reset cost.</p>'+figure('includes-memory','Memory-backed composition',rows,'render','Median ms per prepare + render; 50 samples.')+figure('includes-files','File-backed composition',rows,'files','Median ms per file-backed prepare + render; 50 samples.'))
 rows=[('article','Article'),('nested-loops','Nested loops'),('collection','2k collection'),('transform','Uppercase')]
 out+=section('article','07 / realistic assembly','A page is more than interpolation.','<p>The article combines metadata, navigation, sections, conditional output and a footer. Nested loops and a 2,000-record collection exercise lookup and output growth. Uppercase is the same ASCII transformation in every engine.</p>'+figure('article','Persistent preparation + rendering',rows,'render','Median ms per render; 50 samples; logarithmic axis.',log=True))
 rows=[('many-templates-'+str(n),f'{n:,} templates') for n in [10,100,1000]]
 out+=section('many','08 / source diversity','A thousand distinct templates.','<p>Unique main sources carry distinct output suffixes. Every source is prepared and rendered; this is not a cache-hit claim. Values below are complete workload totals rather than amortized individual template times.</p>'+figure('many-templates','Prepare + render distinct templates',rows,'render','Median total ms per workload; 50 samples; logarithmic axis.',factor=lambda c:int(c.rsplit('-',1)[1]),line=True,log=True))
 rows=[('literal','Literal'),('article','Article'),('collection','2k collection')]
 out+=section('memory','09 / resource scope','Memory belongs to a boundary.','<p>These are unranked raw accounting observations, not memory-efficiency rankings. The final noop-child control rose from 16.75 to 80.75 MiB when its launch parent allocated 64 MiB: inherited wait4 floors can dominate fresh and whole-worker peaks. No constant is subtracted. Persistent-worker lifetime also includes preload, preparation, retained batch outputs and validation; it is not memory per render. Scopes remain separate.</p>'+figure('fresh-memory','Unranked fresh-child RSS accounting',rows,'fresh','Raw median maximum-child RSS MiB; inherited launch floor; unranked, 30–50 invocations per cell.',metric='median_child_rss_mib')+'<details><summary>Persistent-worker high-water observations</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Results, horizontally scrollable"><table><caption>Unranked whole-worker maximum RSS, MiB; launch floor and lifetime scope, not memory per render</caption><thead><tr><th>Workload</th><th>Engine</th><th>Operation</th><th>Peak MiB</th></tr></thead><tbody>'+''.join('<tr><th>'+html.escape(x['case'])+'</th><td>'+NAMES[ENG.index(x['engine'])]+'</td><td>'+x['mode']+'</td><td>'+f'{x["max_process_rss_mib"]:,.3f}'+'</td></tr>' for x in compact['worker_memory'] if x['case'] in ['literal','article','collection'])+'</tbody></table></div></details>')
 out+=section('correctness','10 / independent gates','A faster wrong document is rejected.','<p>Cloud certification passed all 393 supported cells, including a separate raw-special-value fixture. Every timed render is compared against independent expected bytes. Fresh output hashes are retained; persistent workers check every batch output before emitting their timing row. Ordering, record counts, includes and changing-data variants follow the exact output contract.</p><p>The independent audit checks all 375 official cells, the complete sample index set, 17,950 measured observations, 750 separate warmups and every frozen corpus hash. No statistical outliers were removed. Thirty extra special-value/malformed/variant gates passed. Historical newline/Node-stdout preparation failures remain in the archived evidence; final certification and observations passed.</p><details><summary>All measured medians, p95 and ranges</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Results, horizontally scrollable"><table><caption>Fresh ms/invocation; all persistent modes ms/template operation; no boundary pooling</caption><thead><tr><th>Workload</th><th>Engine</th><th>Mode</th><th>Median</th><th>p95</th><th>Min</th><th>Max</th><th>Samples</th></tr></thead><tbody>'+''.join('<tr><th>'+x['case']+'</th><td>'+NAMES[ENG.index(x['engine'])]+'</td><td>'+x['mode']+'</td>'+''.join('<td>'+f'{x[k]:,.4f}'+'</td>' for k in ['median_ms','p95_ms','min_ms','max_ms'])+'<td>'+str(x['samples'])+'</td></tr>' for x in compact['cells'])+'</tbody></table></div></details>')
 prefs=[('Small native text generation','Nift is a credible first choice','Direct embedded renderer; named scopes, expressive text syntax, explicit source/path APIs.'),('Existing Python application','Jinja2','Native Python values and concrete framework integration already in the application.'),('Expressive JS application views','Nunjucks','Native JS data and view composition without a native library deployment dependency.'),('Logic-light JS views with heavy reuse','Handlebars','Compiled functions and application-owned helpers match the desired presentation boundary.'),('Product standardized on Liquid syntax','LiquidJS','Its constrained filters/blocks are the required authoring contract.'),('Nift-owned or mixed-generation project','Nift','Shared expression/composition model plus tracked project ownership.'),('Agent-primary Nift-owned composition','Nift','Explicit scopes/includes and checked output contract within the existing project; standalone prepared workloads remain a host-engine choice.'),('Repeated fixed complex server templates today','A prepared-template engine','A concrete public preparation/reuse capability Nift does not yet expose.')]
 practitioner='''<p class="eyebrow">Qualitative practitioner assessment / not benchmark evidence</p><p><strong>Human + agent:</strong> Nift for Nift-owned composition, Jinja2 for an existing Python application, Handlebars for logic-light JS prepared reuse. <strong>Agent-primary:</strong> the same direct conditional choices; named bindings, source identity and output contracts help automated maintenance, but they do not erase the large source-render gap or missing prepared API. Nift is an attractive text-template language in its own right. Its value expressions, named loop locals and explicit includes make realistic composition inspectable. These are language advantages, independent of the website generator around it.</p><h3>The API matters as much as syntax.</h3><p>Nift’s source-versus-path distinction and per-render Context separate data, source policy and execution cleanly. Jinja/Nunjucks remain familiar and expressive in their existing hosts. Handlebars and Liquid deliberately restrict logic; that can make a presentation layer easier to maintain, rather than weaker.</p><p>The implementation exposed concrete conventions: Jinja’s dot lookup collided with a dictionary key named items, and its default newline policy changed bytes. Handlebars compile is lazy, so prepared functions must be forced before a reuse timer. Exact fixtures caught these differences. Nift source caching also needed explicit filesystem treatment.</p><h3>What would I want an agent to maintain?</h3><p>Named bindings, predictable scopes, explicit composition and a declared output/escaping contract matter more than minimum character count. Nift’s richer functions can remove awkward helper plumbing, but business policy and side effects should not drift into templates accidentally. Formatted Nift, Jinja and Nunjucks are all good representations; constrained Handlebars/Liquid can be preferable when the project wants a smaller editing surface.</p><div class="decision table-scroll"><table><caption>Current preferences at equal performance: requirements, not a universal ranking</caption><thead><tr><th>Requirement</th><th>Preference</th><th>Reason</th></tr></thead><tbody>'''+''.join('<tr><th>'+a+'</th><td>'+b+'</td><td>'+c+'</td></tr>' for a,b,c in prefs)+'''</tbody></table></div><h3>Present-day versus mature Nift.</h3><p>A public prepared-template artifact is the major standalone gap. I want explicit source identity, include invalidation, lifetime and concurrency contracts—not an undocumented benchmark fast path. If those become reliable and repeated-render performance is comparable, I see no architectural requirement to retain another renderer underneath Nift.</p><p>Existing Python/JS projects may still choose their host engine because of concrete value/framework/deployment requirements. Nift-owned projects already have a compelling single-model advantage. AI-DX authoring safety is qualitative: autonomous edit success, partial-error recovery and product-native structured feedback were not measured. Harness JSON is not a product feature. Context-sensitive HTML escaping, sandboxing, async filters, localization and streaming were not certified by this text-rendering campaign.</p><p><a href="'''+experiment+'''/docs/NIFT-TEMPLATE-ENGINE-DX-REVIEW.md">Full practitioner review ↗</a></p>'''
 out+=section('practitioner','11 / practitioner view','Would I actually use Nift as a template engine?',practitioner)
 out+=section('method','12 / frozen evidence','Every number has a source.','<p>One fresh g6-standard-4 shared-CPU Linode, us-east, Ubuntu 24.04. AMD EPYC 7642 host CPU, 4 shared vCPUs / 8 GiB RAM, Linux 6.8.0-134-generic, Python 3.12.3 and Node 22.22.1. All participants use one CPU affinity; order rotates within each round. Two separate warmup rounds, workload-sensitive fresh counts and 50 persistent samples. Batches are frozen from local feasibility. There is no machine-cold cache claim.</p><p class="source-id">Nift source: '+source+'<br>Measured suite: '+suite+'<br>Canonical evidence: '+args.commit+'<br>Experiment assessment/audit: '+args.experiment_commit+'</p><p><a href="'+evidence+'">Raw observations, warmups, environment, hashes and audit ↗</a> · <a href="'+experiment+'/docs/ADAPTER-BOUNDARIES.md">Adapter boundaries ↗</a> · <a href="'+experiment+'/docs/METHODOLOGY.md">Protocol ↗</a></p><p>Publication contains compact summary statistics and these displayed figures. Raw samples, corpora, traces and lifecycle receipts remain in the evidence repository. Existing reports and graph designs are preserved.</p>')
 out+='</main>'
 (dest/'index.html').write_text(out+'\n')
 print('publication summary bytes',(dest/'published.json').stat().st_size,'report bytes',len(out.encode()))
if __name__=='__main__':main()
